	/** 
	 * jumpstart the process by instantiating2 Item
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		itemId = ItemService.getItemInstance()
		.createItem( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ItemService.getItemInstance()
				.createItem( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.itemSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Item : " + successValue.getItemId());
							  if (successValue.getItemId().equals(itemId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfItemList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Item test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on item consumed")
					);
			subscriber.itemSubscribe( itemId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Item : " + successValue.getItemId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfItemList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on item for itemId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Item. 
	 */
	protected Item read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Item" );

		Item entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Item with primary key" );
		msg.append( itemId );
		
		ItemFetchOneSummary fetchOneSummary = new ItemFetchOneSummary( itemId );

		try {
			entity = ItemService.getItemInstance().getItem( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Item " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Item.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Item." );

		StringBuilder msg = new StringBuilder( "Failed to update a Item : " );        
		Item entity = read();
		UpdateItemCommand command = generateUpdateCommand();
		command.setItemId(entity.getItemId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Item." );

			// for use later on...
			itemId = entity.getItemId();

			ItemService proxy = ItemService.getItemInstance();  

			proxy.updateItem( command ).get();

			LOGGER.info( "-- Successfully saved Item - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + itemId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Item.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Item." );

		Item entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Item with id " + itemId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Item with id " + itemId );

			throw e;
		}

		try{
			ItemService.getItemInstance().delete( new DeleteItemCommand( entity.getItemId() ) ).get();
			LOGGER.info( "-- Successfully deleted Item with id " + itemId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Item with id " + itemId );

			throw e;
		}
	}

	/**
	 * get all Items.
	 */
	protected List<Item> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Items:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Item : " );        
		List<Item> collection  = new ArrayList<>();

		try {
			// call the static get method on the ItemService
			collection = ItemService.getItemInstance().getAllItem();
			assertNotNull( collection, "An Empty collection of Item was incorrectly returned.");
			
			// Now print out the values
			Item entity = null;            
			Iterator<Item> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getItemId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

